import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int T = sc.nextInt();

        long ans;
        if (T == 0) {
            ans = N;
        } else if (T == 1) {
            ans = (long) N * (N - 1);
        } else {
            if (N < 3) {
                ans = 0;
            } else {
                ans = (long) N * (N - 1) * (N - 2) / 6;
            }
        }

        System.out.println(ans);
    }
}
